package org.eclipse.rdf4j.sail.lmdb;

/** Event-order contracts on the progress helper used by the actual continuous guest writer. */
public final class CrashPowerCutProgressTestMain {
	private CrashPowerCutProgressTestMain() {
	}

	public static void main(String[] args) {
		if (args.length != 1) {
			throw new IllegalArgumentException("usage: CrashPowerCutProgressTestMain <event-order>");
		}
		CrashPowerCutWriterMain.RunningProgress progress = new CrashPowerCutWriterMain.RunningProgress();
		progress.startGeneration(1);
		progress.transactionStarted();
		progress.commitReturned();
		check(!progress.ready("journal-replay"), "One returned generation cannot be ready");
		progress.startGeneration(2);
		progress.transactionStarted();
		switch (args[0]) {
		case "replay-before-spill" -> {
			progress.replayCompleted();
			progress.spillObserved(2);
			progress.commitReturned();
			check(progress.spilledReplays() == 0, "Spill after replay must not qualify as a spilled replay");
			check(!progress.ready("journal-replay"), "Replay trial cannot be ready without causal spilled replay");
		}
		case "spill-before-replay" -> {
			progress.spillObserved(2);
			progress.replayCompleted();
			progress.replayCompleted();
			progress.commitReturned();
			check(progress.spilledReplays() == 1, "Spill observed before replay must qualify");
			check(progress.ready("journal-replay"), "Two returned generations with causal replay must be ready");
		}
		case "foreign-generation-spill" -> {
			progress.spillObserved(1);
			progress.replayCompleted();
			progress.commitReturned();
			check(progress.spilledReplays() == 0, "Another generation's spill must not qualify");
			check(!progress.ready("journal-replay"), "Foreign spill cannot make a replay trial ready");
		}
		default -> throw new IllegalArgumentException("Unknown event order " + args[0]);
		}
		System.out.println("PASS " + args[0]);
	}

	private static void check(boolean condition, String message) {
		if (!condition) {
			throw new AssertionError(message);
		}
	}
}
